  if (style.base) {
    const inner = text.startsWith(style.prefix) && text.endsWith(style.suffix) ? text.slice(style.prefix.length, -style.suffix.length) : text;
    return style.prefix + styledText(inner, style.base) + style.suffix;
  }
  const upper = style.upper && Array.from(style.upper), lower = style.lower && Array.from(style.lower);
